[ApiController]
[Route("api/products")]
public class ProductsController : ControllerBase
{
    private readonly IProductService _svc;
    public ProductsController(IProductService svc) => _svc = svc; // DI injects the service

    [HttpGet("{id}")]                         // GET api/products/5 maps to this action
    public async Task<ActionResult<Product>> Get(int id)
    {
        var product = await _svc.FindAsync(id);
        return product is null ? NotFound() : Ok(product); // 404 vs 200 + JSON automatically
    }
}
